def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)

    # Residual graph edges: [to, reverse_index, capacity, cost]
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Send k units of flow from the first time to the last, minimizing cost.
    # Initial potentials make all reduced costs nonnegative.
    potential = [0] * n
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity and v > u and cost < 0:
                potential[v] = min(potential[v], potential[u] + cost)

    total_cost = 0
    source, sink = 0, n - 1

    for _ in range(k):
        dist = [float("inf")] * n
        prev_node = [-1] * n
        prev_edge = [-1] * n
        dist[source] = 0
        used = [False] * n

        # Dijkstra on nonnegative reduced costs; the graph has at most 601 nodes.
        for _step in range(n):
            u = -1
            best = float("inf")
            for i in range(n):
                if not used[i] and dist[i] < best:
                    best = dist[i]
                    u = i
            if u == -1:
                break
            used[u] = True

            for ei, (v, _, capacity, cost) in enumerate(graph[u]):
                if capacity:
                    reduced = cost + potential[u] - potential[v]
                    nd = dist[u] + reduced
                    if nd < dist[v]:
                        dist[v] = nd
                        prev_node[v] = u
                        prev_edge[v] = ei

        for v in range(n):
            if dist[v] < float("inf"):
                potential[v] += dist[v]

        v = sink
        while v != source:
            u = prev_node[v]
            ei = prev_edge[v]
            edge = graph[u][ei]
            edge[2] -= 1
            graph[v][edge[1]][2] += 1
            total_cost += edge[3]
            v = u

    return -total_cost
